      "sql": "CREATE TRIGGER index_moc_edges_insert AFTER INSERT ON moc_edges BEGIN INSERT OR REPLACE INTO index_edges(generation,parent_id,child_id,parent_revision,child_revision)\n      SELECT (SELECT active_generation FROM namespace_index_state s WHERE s.owner_id = p.owner_id AND s.scope = p.scope AND s.project_id = p.project_id),r.parent_id,r.child_id,r.parent_revision,r.child_revision\n      FROM moc_edges r JOIN mocs p ON p.id = r.parent_id JOIN mocs c ON c.id = r.child_id WHERE r.parent_id = NEW.parent_id AND r.child_id = NEW.child_id AND p.owner_id = c.owner_id AND p.scope = c.scope AND p.project_id = c.project_id AND p.level = 2 AND c.level = 1 AND p.revision = r.parent_revision AND c.revision = r.child_revision AND (SELECT active_generation FROM namespace_index_state s WHERE s.owner_id = p.owner_id AND s.scope = p.scope AND s.project_id = p.project_id) IS NOT NULL; END"
